#include <stdio.h>
#include <stdlib.h>

#define ROWS 6
#define COLS 6

int grid[ROWS][COLS];
int visited[ROWS][COLS];
int dist[ROWS][COLS];
int q_row[ROWS * COLS];
int q_col[ROWS * COLS];

void bfs(int row, int col) {
    int front = 0;
    int rear = 0;
    q_row[rear] = row;
    q_col[rear] = col;
    rear++;
    visited[row][col] = 1;
    dist[row][col] = 0;

    while (front < rear) {
        int current_row = q_row[front];
        int current_col = q_col[front];
        front++;

        if (current_row < 0 || current_row >= ROWS || current_col < 0 || current_col >= COLS) {
            printf("INVALID_CELL\n");
            continue;
        }

        if (grid[current_row][current_col] == '#') {
            continue;
        }

        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                if (abs(i) + abs(j) != 1) {
                    continue;
                }

                int new_row = current_row + i;
                int new_col = current_col + j;

                if (new_row < 0 || new_row >= ROWS || new_col < 0 || new_col >= COLS) {
                    continue;
                }

                if (visited[new_row][new_col]) {
                    continue;
                }

                visited[new_row][new_col] = 1;
                dist[new_row][new_col] = dist[current_row][current_col] + 1;
                q_row[rear] = new_row;
                q_col[rear] = new_col;
                rear++;
            }
        }
    }
}

int main() {
    // Initialize the grid
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            grid[i][j] = 0;
        }
    }

    // Set some obstacles in the grid
    grid[1][1] = '#';
    grid[2][2] = '#';
    grid[3][3] = '#';

    // Start the BFS from the top-left cell
    bfs(0, 0);

    // Print the distance to each cell
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            printf("dist=%d\n", dist[i][j]);
        }
    }

    return 0;
}
